entries[471399] = { ["name"] = "Formel: Prächtiger Trollschein", ["text"] = "100 Meter Reichweite\nWirken in 3 sek.\nLehrt Euch, wie man prächtigen Trollschein herstellt." }
entries[471400] = { ["name"] = "Prächtiger Trollschein", ["text"] = "Wirken in 5 sek.\nTools: Runenverzierte Arkanitrute\nReagenzien:\nFläschchen Mojo (3), Fläschchen großes Mojo (3), Großer glänzender Splitter (2), Magieerfüllte Phiole\nStellt prächtigen Trollschein her.\n45\nBenutzen: Während die Beschichtung auf Eurem Schild aufgetragen ist, sind Zauberschaden und Heilung um bis zu 36 und Eure kritische Zaubertrefferchance um 1% erhöht. Hält 30 Min. lang an.\n5 Aufladungen" }
entries[471401] = { ["name"] = "Prächtiger Trollschein", ["text"] = "Wirken in 3 sek.\nBenötigt Waffen\nWährend die Beschichtung auf Eurem Schild aufgetragen ist, sind Zauberschaden und Heilung um bis zu 36 und Eure kritische Zaubertrefferchance um 1% erhöht. Hält 30 Min. lang an." }
entries[471402] = { ["name"] = "Zauberschaden erhöhen 36 und 1% Krit", ["text"] = "Erhöht Schaden und Heilung, die durch Zauber und magische Effekte verursacht werden, um bis zu 36. Erhöht zudem Eure kritische Zaubertrefferchance um 1%." }
