entries[473384] = { ["name"] = "Knappen beschwören", ["text"] = "Nahkampfreichweite\nWirken in 1 sek.\nDas Handbuch wird verwendet, um den Argentumknappen für eine Trainingsstunde im Kampf gegen die Silithiden zu rufen. Silithiden, die in Anwesenheit des Knappen getötet werden, steigern Euren Ruf bei der Argentumdämmerung." }
entries[473387] = { ["name"] = "Horn der Dämmerung", ["text"] = "Unbegrenzte Reichweite\nSofort\nSpornt Eure Gruppen- oder Schlachtzugsmitglieder in der Nähe an und gewährt ihnen eine um 10% erhöhte Chance auf kritische Zaubertreffer, eine um 5% erhöhte Chance auf kritische Treffer im Nah- und Distanzkampf und eine um 140 erhöhte Angriffskraft. Hält 2 Stunden lang an. Schließt ähnliche Welteffekte aus. Bleibt von Chronostärkungen unbeeinflusst." }
entries[473399] = { ["name"] = "Liedblumenwiegenlied", ["text"] = "30 Meter Reichweite\nSofort\nBeschwört 1 Stunde lang eine Liedblume, die allen Mitgliedern Eurer Gruppe oder Eures Schlachtzugs eine um 5% erhöhte Chance auf einen kritischen Nahkampf-, Distanzkampf- oder Zaubertreffer gewährt und Attribute um 15 erhöht. Schließt ähnliche Welteffekte aus. Bleibt von Chronostärkungen unbeeinflusst." }
entries[473403] = { ["name"] = "Segen von Neptulon", ["text"] = "100 Meter Reichweite\nSofort\nErhöht 2 Stunden lang die Angriffskraft aller Mitglieder Eurer Gruppe oder Eures Schlachtzugs in der Nähe um 200, die Ausdauer um 15% und die kritische Trefferchance von Zaubern 3%. Schließt ähnliche Welteffekte aus. Bleibt von Chronostärkungen unbeeinflusst." }
entries[473441] = { ["name"] = "Macht von Blackrock", ["text"] = "Unbegrenzte Reichweite\nSofort\nErhöht die Gesundheit um 300. 15% Tempo für Nahkampfangriffe. 10 Mana alle 5 Sek." }
entries[473450] = { ["name"] = "Dunkles Schicksal des Schadens", ["text"] = "Unbegrenzte Reichweite\nSofort\nErhöht 2 Stunden lang den verursachten Schaden aller Mitglieder Eurer Gruppe oder Eures Schlachtzugs um 10%." }
entries[473466] = { ["name"] = "Feuerwasserkessel", ["text"] = "30 Meter Reichweite\nSofort\nBeschwört einen Feuerwasserkessel, der 10 Min. lang bestehen bleibt und von allen Mitgliedern Eurer Gruppe oder Eures Schlachtzugs benutzt werden kann, um 1 Stunde lang die Nahkampfangriffskraft um 35 und die Größe zu erhöhen." }
entries[473469] = { ["name"] = "Geläutertes Feuerwasser", ["text"] = "Sofort\nErhöht 1 Stunde lang Eure Nahkampfangriffskraft um 35 sowie auch Eure Größe." }
entries[473476] = { ["name"] = "Träume von Zandalar", ["text"] = "Unbegrenzte Reichweite\nSofort\nErhöht bei allen Mitgliedern Eurer Gruppe oder Eures Schlachtzugs 2 Stunden lang die Bewegungsgeschwindigkeit um 10% und die Werte um 15%." }
entries[473477] = { ["name"] = "Liedblumenserenade" }
entries[473482] = { ["name"] = "Elementartrennung", ["text"] = "20 Meter Reichweite\nSofort\nSchwächt die Elementarmitglieder des Abyssischen Rates in Silithus, wodurch der von ihnen verursachte Schaden um 20% verringert wird. Hält 2 Min. lang an." }
entries[473493] = { ["name"] = "Explosive Sandfalle", ["text"] = "35 Meter Reichweite\n15 sek. Abklingzeit\nPlatziert eine Falle an einem Ort in der Nähe, die explodiert, wenn sich ein Silithid des Ashischwarms, Regalschwarms oder Zoraschwarms nähert, wodurch der Silithid 15 Sek. lang alle 3 Sek. Schaden in Höhe von 6% seiner Gesundheit erleidet." }
