entries[473525] = { ["name"] = "Frostomatikstrahl", ["text"] = "35 Meter Reichweite\nFriert einen Silithiden im Bau des Ashischwarms, im Bau des Regalschwarms oder im Bau des Zoraschwarms für 1 Min. ein. Effekt wird durch jeden Schaden unterbrochen." }
entries[473544] = { ["name"] = "Schleichen", ["text"] = "Sofort\nDurch das Einatmen dieses Weihrauchs verschwindet Ihr in die Schatten, was ein unbemerktes Herumschleichen im Bau des Ashischwarms, im Bau des Regalschwarms und im Bau des Zoraschwarms ermöglicht, jedoch wird Eure Geschwindigkeit um 50% verringert. Hält 1 Min. lang an." }
