entries[473900] = { ["name"] = "Gezähmte Silithidendrohne beschwören", ["text"] = "Wirken in 3 sek.\nStößt ein Hochfrequenzsignal aus, das eine Silithidendrohne dazu zwingt, sich aus dem Boden unter dem Tempel von Ahn'Qiraj an die Oberfläche zu graben. Der Silithid gehorcht seinem Beschwörer und kann innerhalb des Tempels von Ahn'Qiraj als Reittier benutzt werden. Jegliche feindselige Handlung gegen den Reiter zwingen die Drohne, sich wieder einzugraben." }
