entries[474142] = { ["name"] = "Wirre Gedanken", ["text"] = "Schaden verursachende Zauber, die keinen regelmäßigen Schaden verursachen, erhöhen Euren Zauberschaden 15 Sek. lang um 15. Wenn das Ziel von einem Spielercharakter kontrolliert wird, wird stattdessen Euer Zauberdurchschlag 15 Sek. lang um 100 erhöht.\n(15s Abklingzeit)" }
