entries[474400] = { ["name"] = "Wahnsinn verursachen", ["text"] = "30 Meter Reichweite\nSofort\nTreibt ein gegnerisches Ziel für begrenzte Zeit in den Wahnsinn, erhöht sein Angriffstempo um 50% und seine Bewegung um 80% und lässt es außerdem 6 Sek. lang seine eigenen Verbündeten angreifen. Betroffene Ziele erleiden 90% weniger Schaden." }
