entries[1213480] = { ["name"] = "Totem der Erdbindung", ["text"] = "40 Mana\nSofort\nTools: Erdtotem\nBeschwört ein Totem der Erdbindung, das 45 Sek. lang bestehen bleibt und in regelmäßigen Abständen die Bewegungsgeschwindigkeit von Gegnern in der Nähe auf 50% der normalen Geschwindigkeit verringert." }
entries[1213481] = { ["name"] = "Klingenstachelhirnkasten", ["text"] = "Wirken in 1 min\nTools: Schmiedehammer\nReagenzien:\nArkanitbarren (15), Obsidianangereicherter Thoriumbarren (3), Verzaubertes Leder (4), Tückische Klaue (10), Monströses Silithidenchitin (4)\nKlingenstachelhirnkasten\nWird beim Anlegen gebunden\nKopf Platte\n722 Rüstung\n+14 Stärke\n+40 Ausdauer\nHaltbarkeit 100 / 100\n60\nAnlegen: Bei einem Treffer im Kampf erleidet der Angreifer 100 Naturschaden. Verursacht das Doppelte des verursachten Schadens an Bedrohung.\nAnlegen: Verteidigung +9." }
