entries[1213544] = { ["name"] = "Fläschchen des unnachgiebigen Kummers", ["text"] = "Wirken in 25 sek.\nTools: Stein der Weisen\nReagenzien:\nGroße ewige Essenz , Schwarmdistel , Fläschchen mit destillierter Weisheit , Kristallphiole\n60\nBenutzen: Erhöht 2 Stunden lang die hervorgerufene Heilung von Zaubern und magischen Effekten um bis zu 80 Gesundheit, den Schaden von Zaubern und magischen Effekten um bis zu 27 und die Manaregeneration um 12 Mana pro 5 Sek. Es kann immer nur der Effekt von jeweils einem Fläschchen aktiv sein. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)" }
